//! Campaign Models and Draft Generators for Proactive Operations.

use serde::{Deserialize, Serialize};

/// The concrete plan generated by the autonomous campaign engine.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CampaignPlan {
    pub campaign_code: String,
    pub title: String,
    pub channel: String,
    pub target_recipient: String,
    pub message_body: String,
    pub requires_holding_pattern_approval: bool,
    pub holding_reason: Option<String>,
}

/// Generates an Accounts Receivable (AR) Debt Collection message with dynamic QRIS link.
pub fn build_ar_debt_plan(
    invoice_id: &str,
    customer_name: &str,
    customer_phone: &str,
    amount_cents: i64,
    days_overdue: u32,
) -> CampaignPlan {
    let amount_idr = amount_cents / 100;
    let payment_link = format!("https://pay.archzxy.com/qris/{}", invoice_id);

    let message_body = format!(
        "Halo Kak {}, semoga sehat selalu. Mengingatkan tagihan #{} sebesar Rp {} telah jatuh tempo {} hari yang lalu. Pembayaran instan via QRIS dapat dilakukan di: {}. Terima kasih!",
        customer_name, invoice_id, amount_idr, days_overdue, payment_link
    );

    // Amounts > Rp 10.000.000 (1,000,000,000 cents) require owner holding pattern approval
    let requires_holding = amount_cents > 1_000_000_000;
    let holding_reason = if requires_holding {
        Some(format!(
            "High-value AR reminder (> Rp 10.000.000) for customer '{}' requires owner confirmation.",
            customer_name
        ))
    } else {
        None
    };

    CampaignPlan {
        campaign_code: format!("AR-{}", invoice_id),
        title: format!("AR Follow-up: {}", customer_name),
        channel: "whatsapp".into(),
        target_recipient: customer_phone.into(),
        message_body,
        requires_holding_pattern_approval: requires_holding,
        holding_reason,
    }
}

/// Generates a Purchase Order draft when inventory drops below reorder point.
pub fn build_reorder_po_plan(
    sku: &str,
    item_name: &str,
    reorder_qty: i32,
    supplier_id: &str,
) -> CampaignPlan {
    let message_body = format!(
        "DRAFT PURCHASE ORDER: Supplier ID '{}' for {} units of SKU '{}' ({}).",
        supplier_id, reorder_qty, sku, item_name
    );

    CampaignPlan {
        campaign_code: format!("PO-{}", sku),
        title: format!("Auto-Replenish: {}", item_name),
        channel: "internal_po".into(),
        target_recipient: supplier_id.into(),
        message_body,
        requires_holding_pattern_approval: true,
        holding_reason: Some(format!(
            "Supplier purchase order generation for SKU '{}' requires manager stamp.",
            sku
        )),
    }
}
